contracts.obligation:
let buf = [1u8, 2, 3];
let recv = &buf[..];
let out = recv.as_virt_ptr();
let expected = buf.as_ptr() as usize;
assert(out.vaddr == expected);

let first = Jiffies::elapsed();
let first_v = first.as_u64();
let out = Jiffies::elapsed();
let second_v = out.as_u64();
assert(second_v >= first_v);
